-- Local replay required before any staging promotion.
-- OTOTR EXPENSE APPROVAL SUBMIT RPC CANDIDATE
create or replace function finance_private.current_expense_approval_committer_is_trusted() returns boolean language sql stable security definer set search_path='' as $$select false$$;
create or replace function finance_private.resolve_expense_approval_scope(p_actor_id uuid,p_expense_id uuid,p_permission text) returns boolean language sql stable security definer set search_path='' as $$select false$$;
create or replace function finance_private.resolve_expense_financial_snapshot_context(p_expense_id uuid) returns jsonb language sql stable security definer set search_path='' as $$select null::jsonb$$;
create or replace function finance_private.build_expense_approval_snapshot(p_expense_id uuid) returns jsonb language plpgsql stable security definer set search_path=pg_catalog,finance,finance_private as $$declare e finance.pass_through_expenses%rowtype;fd finance.fee_definitions%rowtype;ctx jsonb;docs jsonb;shares jsonb;begin select * into e from finance.pass_through_expenses where id=p_expense_id;if not found then return null;end if;select * into fd from finance.fee_definitions where id=e.fee_definition_id;ctx:=finance_private.resolve_expense_financial_snapshot_context(e.id);if ctx is null or not(ctx?'taxMappingVersion' and ctx?'accountingMappingVersion' and ctx?'dueRuleVersion' and ctx?'dueData') then raise exception using errcode='23514',message='approved tax accounting and due context required';end if;select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('documentId',dr.external_document_id,'purposeCode',dl.purpose_code,'contentHash',dr.content_hash,'version',dr.version) order by dr.external_document_id,dl.purpose_code),'[]'::jsonb) into docs from finance.document_links dl join finance.document_references dr on dr.id=dl.document_reference_id and dr.status='ACTIVE' where dl.legal_entity_id=e.legal_entity_id and dl.subject_type='PASS_THROUGH_EXPENSE' and dl.subject_id=e.id;if pg_catalog.jsonb_array_length(docs)=0 then raise exception using errcode='23514',message='active expense evidence required';end if;select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('shareId',s.id,'dealerAccountId',s.dealer_account_id,'branchId',s.branch_id,'method',s.allocation_method,'ruleReference',s.distribution_rule_reference,'basisValue',s.basis_value::text,'allocationRate',s.allocation_rate::text,'net',s.net_amount::text,'tax',s.tax_amount::text,'gross',s.share_amount::text,'order',s.allocation_order,'snapshotHash',s.snapshot_hash) order by s.allocation_order,s.branch_id),'[]'::jsonb) into shares from finance.expense_shares s where s.pass_through_expense_id=e.id;if pg_catalog.jsonb_array_length(shares)=0 then raise exception using errcode='23514',message='calculated expense shares required';end if;if (select coalesce(pg_catalog.sum(s.net_amount),0)<>e.distributable_net_amount or coalesce(pg_catalog.sum(s.tax_amount),0)<>e.distributable_tax_amount or coalesce(pg_catalog.sum(s.share_amount),0)<>e.distributable_amount from finance.expense_shares s where s.pass_through_expense_id=e.id) then raise exception using errcode='23514',message='expense approval control totals mismatch';end if;return pg_catalog.jsonb_build_object('expenseId',e.id,'legalEntityId',e.legal_entity_id,'supplierReferenceNormalized',e.supplier_reference_normalized,'expenseDate',e.expense_date,'currencyCode',e.currency_code,'sourceTotals',pg_catalog.jsonb_build_object('net',e.source_net_amount::text,'tax',e.source_tax_amount::text,'gross',e.source_amount::text),'distributableTotals',pg_catalog.jsonb_build_object('net',e.distributable_net_amount::text,'tax',e.distributable_tax_amount::text,'gross',e.distributable_amount::text),'feeDefinition',pg_catalog.jsonb_build_object('id',fd.id,'code',fd.code,'family',fd.fee_family,'version',fd.version_no),'documents',docs,'allocationPolicy',e.allocation_policy,'shares',shares,'financialMappings',ctx);end$$;
create or replace function finance_api.authorize_expense_submit_approval(p_expense_id uuid,p_permission text) returns boolean language sql stable security definer set search_path='' as $$select auth.uid() is not null and p_permission='finance.expenses.submit' and finance_private.resolve_expense_approval_scope(auth.uid(),p_expense_id,p_permission)$$;
create or replace function finance_api.commit_expense_submit_approval(p_actor_id uuid,p_expense_id uuid,p_expected_version bigint,p_reason_code text,p_note_hash text,p_idempotency_key text,p_intent_hash text,p_correlation_id uuid) returns jsonb language plpgsql security definer set search_path=pg_catalog,finance,finance_private as $$declare e finance.pass_through_expenses%rowtype;existing jsonb;snapshot jsonb;snapshot_hash text;approval_id uuid;new_version bigint;payload jsonb;previous text;audit_hash text;begin if not finance_private.current_expense_approval_committer_is_trusted() then raise exception using errcode='42501',message='trusted expense approval committer required';end if;if p_expected_version<1 or length(btrim(coalesce(p_idempotency_key,''))) not between 8 and 200 or p_intent_hash!~'^[a-fA-F0-9]{64}$' or (p_note_hash is not null and p_note_hash!~'^[a-fA-F0-9]{64}$') then raise exception using errcode='22023',message='invalid expense submit command';end if;select * into e from finance.pass_through_expenses where id=p_expense_id for update;if not found then raise exception using errcode='P0002',message='expense not found';end if;select om.payload into existing from finance.outbox_messages om where om.legal_entity_id=e.legal_entity_id and om.event_type='PASS_THROUGH_EXPENSE_SUBMITTED' and om.aggregate_id=e.id and om.payload->>'idempotencyKey'=p_idempotency_key order by om.created_at_utc desc,om.id desc limit 1;if found then if existing->>'intentHash'=p_intent_hash then return pg_catalog.jsonb_build_object('outcome','REPLAY','expenseId',e.id,'status','PENDING_APPROVAL','version',(existing->>'version')::bigint,'approvalRequestId',existing->>'approvalRequestId','snapshotHash',existing->>'snapshotHash');end if;return pg_catalog.jsonb_build_object('outcome','CONFLICT');end if;if e.status<>'CALCULATED' or e.version<>p_expected_version or e.prepared_by<>p_actor_id then return pg_catalog.jsonb_build_object('outcome','CONFLICT');end if;snapshot:=finance_private.build_expense_approval_snapshot(e.id);snapshot_hash:=pg_catalog.encode(extensions.digest(pg_catalog.convert_to(snapshot::text,'UTF8'),'sha256'),'hex');insert into finance.approval_requests(legal_entity_id,subject_type,subject_id,approval_policy_version,prepared_by,subject_snapshot,subject_snapshot_hash,status,version,created_by,correlation_id) values(e.legal_entity_id,'PASS_THROUGH_EXPENSE',e.id,'EXPENSE_APPROVAL_V1',p_actor_id,snapshot,snapshot_hash,'PENDING',1,p_actor_id,p_correlation_id) returning id into approval_id;insert into finance.approval_steps(approval_request_id,step_no,required_role,created_by,correlation_id) values(approval_id,1,'finance-expense-approver',p_actor_id,p_correlation_id);new_version:=e.version+1;update finance.pass_through_expenses set status='PENDING_APPROVAL',version=new_version,correlation_id=p_correlation_id where id=e.id;payload:=pg_catalog.jsonb_build_object('expenseId',e.id,'approvalRequestId',approval_id,'snapshotHash',snapshot_hash,'version',new_version,'idempotencyKey',p_idempotency_key,'intentHash',p_intent_hash,'reasonCode',p_reason_code,'noteHash',p_note_hash);insert into finance.outbox_messages(legal_entity_id,topic,event_type,aggregate_type,aggregate_id,aggregate_version,payload,payload_hash,status,correlation_id) values(e.legal_entity_id,'finance.expense','PASS_THROUGH_EXPENSE_SUBMITTED','PASS_THROUGH_EXPENSE',e.id,new_version,payload,snapshot_hash,'PENDING',p_correlation_id);perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('audit:'||e.legal_entity_id::text,0));select integrity_hash into previous from finance.audit_events where legal_entity_id=e.legal_entity_id order by created_at_utc desc,id desc limit 1;audit_hash:=pg_catalog.encode(extensions.digest(pg_catalog.convert_to(coalesce(previous,'GENESIS')||':'||e.id::text||':PASS_THROUGH_EXPENSE_SUBMITTED:'||snapshot_hash||':'||p_correlation_id::text,'UTF8'),'sha256'),'hex');insert into finance.audit_events(legal_entity_id,actor_id,actor_type,action_code,subject_type,subject_id,decision,reason_code,before_hash,after_hash,previous_integrity_hash,integrity_hash,safe_context,correlation_id) values(e.legal_entity_id,p_actor_id,'USER','PASS_THROUGH_EXPENSE_SUBMITTED','PASS_THROUGH_EXPENSE',e.id,'ALLOW',p_reason_code,e.input_hash,snapshot_hash,previous,audit_hash,pg_catalog.jsonb_build_object('approvalRequestId',approval_id,'noteHash',p_note_hash,'previousVersion',e.version),p_correlation_id);return pg_catalog.jsonb_build_object('outcome','SUBMITTED','expenseId',e.id,'status','PENDING_APPROVAL','version',new_version,'approvalRequestId',approval_id,'snapshotHash',snapshot_hash);end$$;
revoke all on function finance_private.current_expense_approval_committer_is_trusted() from public,anon,authenticated;revoke all on function finance_private.resolve_expense_approval_scope(uuid,uuid,text) from public,anon,authenticated;revoke all on function finance_private.resolve_expense_financial_snapshot_context(uuid) from public,anon,authenticated;revoke all on function finance_private.build_expense_approval_snapshot(uuid) from public,anon,authenticated;revoke all on function finance_api.authorize_expense_submit_approval(uuid,text) from public,anon;grant execute on function finance_api.authorize_expense_submit_approval(uuid,text) to authenticated;revoke all on function finance_api.commit_expense_submit_approval(uuid,uuid,bigint,text,text,text,text,uuid) from public,anon,authenticated;
